"""
產生 public/data/programs.json：台大學分學程的總學分、規定摘要與課程清單。

課程清單來源是各學程網站與台大課程網，格式各異無法統一爬取，因此以人工整理、分批補齊。
只收課程識別碼、課名、學分與所屬模組，不收授課教師與聯絡人資料。

用法：python scripts/programs-data.py
"""
import json
from pathlib import Path

PROGRAMS = []


def prog(code, name, total, rules, groups=None, courses=None):
    entry = {"code": code, "name": name, "total": total, "rules": rules, "courses": courses or []}
    if groups:
        entry["groups"] = groups
    PROGRAMS.append(entry)


def ids(group, rows):
    """(識別碼, 課名, 學分)"""
    return [{"identifier": i, "name": n, "credits": c, "group": group} for i, n, c in rows]


def names(group, rows):
    """只有課名的清單：(課名, 學分)，以課名比對"""
    return [{"name": n, "credits": c, "group": group} for n, c in rows]


